150: func (j *jwtHelper) doExtract(ctx context.Context, auxJWT *requestv1.AuxData_JWT, parseOpts []jwt.ParseOption) (map[string]*structpb.Value, error) {
151: 	token, err := jwt.ParseString(auxJWT.Token, parseOpts...)
152: 	if err != nil {
153: 		switch {
154: 		case errors.Is(err, jwt.InvalidAudienceError()):
155: 			return nil, fmt.Errorf("invalid audience ('aud')")
156: 		case errors.Is(err, jwt.InvalidIssuedAtError()):
157: 			return nil, fmt.Errorf("issued at time is in the future ('iat')")
158: 		case errors.Is(err, jwt.InvalidIssuerError()):
159: 			return nil, fmt.Errorf("invalid issuer ('iss')")
160: 		case errors.Is(err, jwt.TokenExpiredError()):
161: 			return nil, fmt.Errorf("token has expired ('exp')")
162: 		case errors.Is(err, jwt.TokenNotYetValidError()):
163: 			return nil, fmt.Errorf("token is not yet valid ('nbf')")
164: 		default:
165: 			return nil, fmt.Errorf("failed to parse: %w", err)
166: 		}
167: 	}
168: 
169: 	jwtPBMap := make(map[string]*structpb.Value)
170: 	for _, key := range token.Keys() {
171: 		var v any
172: 		err := token.Get(key, &v)
173: 		if err != nil {
174: 			logging.FromContext(ctx).Named("auxdata").
175: 				Warn("Ignoring JWT key-value pair because the value could not be read", zap.String("key", key), zap.Error(err))
176: 			continue
177: 		}
178: 
179: 		value, err := util.ToStructPB(v)
180: 		if err != nil {
181: 			logging.FromContext(ctx).Named("auxdata").
182: 				Warn("Ignoring JWT key-value pair because the value is not in a known format", zap.String("key", key), zap.Any("value", v), zap.Error(err))
183: 			continue
184: 		}
185: 
186: 		jwtPBMap[key] = value
187: 	}
188: 
189: 	return jwtPBMap, nil
190: }

