		return nil, &JWTValidationError{Friendly: fmt.Errorf("invalid audience ('aud')"), Underlying: err}
	case errors.Is(err, jwt.InvalidIssuedAtError()):
		return nil, &JWTValidationError{Friendly: fmt.Errorf("issued at time is in the future ('iat')"), Underlying: err}
	case errors.Is(err, jwt.InvalidIssuerError()):
		return nil, &JWTValidationError{Friendly: fmt.Errorf("invalid issuer ('iss')"), Underlying: err}
	case errors.Is(err, jwt.TokenExpiredError()):
		return nil, &JWTValidationError{Friendly: fmt.Errorf("token has expired ('exp')"), Underlying: err}
	case errors.Is(err, jwt.TokenNotYetValidError()):
		return nil, &JWTValidationError{Friendly: fmt.Errorf("token is not yet valid ('nbf')"), Underlying: err}
	default:
		return nil, fmt.Errorf("failed to parse: %w", err)
	}
}

